"""Hand-written, checked explanations for the money questions people actually ask.

Why a library and not a language model: an answer about money must be right every time, so each explanation here was
written once, in English and Hindi, and is shown as written. A model is only ever used to PICK which entry fits a
question (backend/understand.py); it never writes the answer and never supplies a number.

Rules that keep it honest:
  * a rule of thumb is called a rule of thumb, with the reason it exists and when it does not apply;
  * a rate, a limit or a tax rate that can change carries "as of" wording and tells the person to confirm it;
  * nothing here tells anyone to buy or sell a particular security.
"""
from __future__ import annotations

import re
from typing import Any


def C(cid: str, cat: str, rx: str, questions: list[str], head: tuple[str, str], points: tuple[list[str], list[str]],
      watch: tuple[str, str], follow: list[tuple[str, str]], table: dict | None = None, example: tuple[str, str] | None = None,
      tool: tuple[str, str, str, dict] | None = None, tour: str | None = None) -> dict[str, Any]:
    return {"id": cid, "cat": cat, "rx": re.compile(rx, re.I), "q": questions,
            "head": {"en": head[0], "hi": head[1]}, "points": {"en": points[0], "hi": points[1]},
            "watch": {"en": watch[0], "hi": watch[1]}, "follow": follow, "table": table,
            "example": None if example is None else {"en": example[0], "hi": example[1]},
            "tool": tool, "tour": tour}


