    C("pe_ratio", "Stocks", r"\b(p/?e|price[- ]to[- ]earnings?|price earnings|pe ratio|eps|earnings per share|market cap(italisation|italization)?|roe|return on equity|book value|p/?b ratio|dividend yield|ebitda|debt to equity|free cash flow|peg ratio)\b.{0,30}\b(mean|means|what|why|how|good|high|low|explain|calculate)\b|\bwhat('?s| is| does)\b.{0,12}\b(p/?e|pe ratio|eps|roe|market cap|dividend yield|book value|ebitda|free cash flow|peg)\b",
      ["what is pe ratio", "what does market cap mean", "what is eps", "what is roe", "what is dividend yield", "what is free cash flow"],
      ("These are the standard yardsticks for a company. Each answers one narrow question, so use them together and always compare a company with similar ones, not with all companies.",
       "ये किसी कंपनी को नापने के मानक पैमाने हैं। हर एक एक संकरे सवाल का जवाब देता है, इसलिए उन्हें साथ में इस्तेमाल कीजिए और कंपनी की तुलना सभी कंपनियों से नहीं, समान कंपनियों से कीजिए।"),
      (["P/E (price to earnings): the share price divided by yearly profit per share. P/E 20 means you pay ₹20 for each ₹1 of yearly profit. High can mean growth is expected, or that it is expensive.",
        "EPS (earnings per share): the company's profit divided by the number of shares.",
        "Market cap: share price times number of shares, the market's price for the whole company. It tells you size, not value.",
        "ROE (return on equity): yearly profit as a share of shareholders' money. Above about 15% is often called good, but compare within the industry.",
        "Dividend yield: yearly dividend divided by the share price. A very high yield can be a warning that the price has fallen or the payout is unsustainable.",
        "Free cash flow: the cash left after running the business and investing in it. It is what can really be paid out or used to cut debt.",
        "PEG: P/E divided by the profit growth rate in percent. Under about 1 means you pay little for the growth, over about 2.5 a lot, if the growth lasts."],
       ["P/E (भाव बनाम कमाई): शेयर का भाव भाग प्रति शेयर सालाना मुनाफ़ा। P/E 20 का मतलब सालाना मुनाफ़े के हर ₹1 के लिए ₹20 देना। ऊँचे का मतलब बढ़त की उम्मीद हो सकती है, या कि महँगा है।",
        "EPS (प्रति शेयर कमाई): कंपनी का मुनाफ़ा भाग शेयरों की संख्या।",
        "मार्केट कैप: शेयर का भाव गुणा शेयरों की संख्या, पूरी कंपनी का बाज़ार भाव। यह आकार बताता है, मूल्य नहीं।",
        "ROE (रिटर्न ऑन इक्विटी): सालाना मुनाफ़ा शेयरधारकों के पैसे के हिस्से के रूप में। लगभग 15% से ऊपर को अक्सर अच्छा कहते हैं, पर तुलना अपने उद्योग में कीजिए।",
        "डिविडेंड यील्ड: सालाना डिविडेंड भाग शेयर का भाव। बहुत ऊँची यील्ड चेतावनी हो सकती है कि भाव गिरा है या भुगतान टिकाऊ नहीं।",
        "फ़्री कैश फ़्लो: कारोबार चलाने और उसमें निवेश के बाद बची नक़दी। इसी से असल में भुगतान या क़र्ज़ घटाना हो सकता है।",
        "PEG: P/E भाग मुनाफ़े की बढ़त दर (प्रतिशत में)। लगभग 1 से कम का मतलब बढ़त के लिए कम देना, लगभग 2.5 से ऊपर का ज़्यादा, अगर बढ़त टिके।"]),
      ("A number alone is not a verdict. A low P/E can signal a problem and a high P/E can be deserved.", "अकेली संख्या फ़ैसला नहीं होती। कम P/E किसी समस्या का संकेत हो सकता है और ऊँचा P/E जायज़ भी।"),
      [("Analyse TCS", "TCS का विश्लेषण कीजिए"), ("Compare Infosys and Wipro", "Infosys और Wipro की तुलना कीजिए")],
      tool=("research", "See these for a company", "किसी कंपनी के लिए देखिए", {})),

