BY_ID = {c["id"]: c for c in CONCEPTS}


def keyword_hits(text: str) -> list[tuple[str, float]]:
    """Concepts whose pattern matches, scored by how much of the question the match covers."""
    out = []
    for c in CONCEPTS:
        m = c["rx"].search(text)
        if m:
            out.append((c["id"], 0.5 + min(0.5, len(m.group(0)) / max(20, len(text)))))
    return sorted(out, key=lambda kv: -kv[1])
